\begin{theorem}[Closed manifolds with 2-positive curvature operator]
\label{thm:chow-ii-appd-two-positive-curvature-convergence}
\source{chow-et-al-ricci-flow-part-ii:page-0386}
\uses{thm:chow-ii-boehm-wilking-convergence}
\dcref{appD:D.9}
\group{Ricci Flow Convergence}


Let $n\geq3$. If $(\mathcal M^n,g_0)$ is closed and has 2-positive curvature
operator, its volume-normalized Ricci flow exists for all time and converges
exponentially in every $C^k$ norm to a smooth metric of constant positive
sectional curvature.
\end{theorem}

